float s316_opt(int iterations, int LEN_1D, float* a) {
    float x;
    for (int nl = 0; nl < iterations*5; nl++) {
        x = a[0];
        float temp_x = x;
        for (int i = 1; i < LEN_1D; ++i) {
            float current = a[i];
            if (current < temp_x) {
                temp_x = current;
            }
        }
        x = temp_x;
    }
    return x;
}

typedef float v8f32 __attribute__((__vector_size__(32), __aligned__(32)));
typedef int v8i32 __attribute__((__vector_size__(32), __aligned__(32)));

float vectorized_s316(int iterations, int LEN_1D, float* a) {
    float x = 0.0f;
    int outer_iterations = iterations * 5;

    for (int nl = 0; nl < outer_iterations; nl++) {
        float min_val = a[0];

        // Vectorized reduction
        int i = 1;
        int vec_limit = ((LEN_1D - 1) / 8) * 8 + 1;

        if (vec_limit > 1) {
            v8f32 min_vec = (v8f32){min_val, min_val, min_val, min_val, 
                                   min_val, min_val, min_val, min_val};

            for (; i < vec_limit; i += 8) {
                v8f32 current_vec = *(v8f32*)&a[i];
                v8i32 mask = current_vec < min_vec;
                v8i32 current_i = (v8i32)current_vec;
                v8i32 min_i = (v8i32)min_vec;
                v8i32 blended_i = (mask & current_i) | (~mask & min_i);
                min_vec = (v8f32)blended_i;
            }

            // Horizontal reduction
            float temp_min = min_val;
            float* min_arr = (float*)&min_vec;
            for (int j = 0; j < 8; j++) {
                if (min_arr[j] < temp_min) {
                    temp_min = min_arr[j];
                }
            }
            min_val = temp_min;
        }

        // Scalar tail
        for (; i < LEN_1D; i++) {
            float current = a[i];
            if (current < min_val) {
                min_val = current;
            }
        }

        x = min_val;
    }

    return x;
}
